window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-95373d0bac209d40"]={"versions": [{"id": "FIG-95373d0bac209d40", "releases": ["R3.1.5"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur statischen Schnittstellendefinition innerhalb des AUTOSAR Diagnostic Communication Manager (DCM). Das Diagramm befindet sich in einem UML-Rahmen mit dem Titelkopf <code>class PidServices</code> und spezifiziert die generische Service-Schnittstelle zur Abfrage von OBD-Parameter-IDs (PIDs).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm definiert eine einzelne Schnittstellen-Entität:</p>\n<ul class=\"fig-list\">\n<li><strong><code>«interface» PidServices_&lt;PID&gt;</code></strong>: Generisches Client-Server-Interface für eine spezifische Parameter-ID <code>&lt;PID&gt;</code>.</li>\n<li><strong>Operation</strong>: <code>GetPIDValue(return :Std_ReturnType, DataValueBuffer :uint8*)</code></li>\n<li>Rückgabewert: <code>Std_ReturnType</code> zur Statusrückmeldung der Operationsausführung.</li>\n<li>Parameter: <code>DataValueBuffer :uint8*</code> als Zeiger auf den Datenpuffer zur Aufnahme der abgefragten PID-Nutzdaten.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Schnittstellendiagramm ohne dynamische Interaktions- oder Sequenzabläufe. Die Operation <code>GetPIDValue</code> ist für synchrone Funktionsaufrufe über die AUTOSAR-RTE zwischen DCM und anbietender Software-Komponente ausgelegt.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Definition des Schnittstellen-Musters <code>PidServices_&lt;PID&gt;</code> im AUTOSAR DCM. Für jede unterstützte OBD-PID muss eine entsprechende Schnittstelleninstanz mit der Signatur <code>GetPIDValue</code> bereitgestellt werden, wobei <code>DataValueBuffer</code> vom Typ <code>uint8*</code> die serialisierten Nutzdaten empfängt und <code>Std_ReturnType</code> den Rückgabestatus (<code>E_OK</code>, <code>E_NOT_OK</code>) signalisiert.</p>"}, {"id": "FIG-d815b31ba6c79aee", "releases": ["R3.2.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur statischen Schnittstellendefinition innerhalb des AUTOSAR Diagnostic Communication Manager (DCM). Das Diagramm stellt freistehend die generische Service-Schnittstelle zur Abfrage von OBD-Parameter-IDs (PIDs) dar.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm definiert eine einzelne Schnittstellen-Entität:</p>\n<ul class=\"fig-list\">\n<li><strong><code>«interface» PidServices_&lt;PID&gt;</code></strong>: Generisches Client-Server-Interface für eine spezifische Parameter-ID <code>&lt;PID&gt;</code>.</li>\n<li><strong>Operation</strong>: <code>GetPIDValue(return :Std_ReturnType, DataValueBuffer :uint8*)</code></li>\n<li>Rückgabewert: <code>Std_ReturnType</code> zur Statusrückmeldung der Operationsausführung.</li>\n<li>Parameter: <code>DataValueBuffer :uint8*</code> als Zeiger auf den Datenpuffer zur Aufnahme der abgefragten PID-Nutzdaten.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Schnittstellendiagramm ohne dynamische Interaktions- oder Sequenzabläufe. Die Operation <code>GetPIDValue</code> ist für synchrone Funktionsaufrufe über die AUTOSAR-RTE zwischen DCM und anbietender Software-Komponente ausgelegt.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Definition des Schnittstellen-Musters <code>PidServices_&lt;PID&gt;</code> im AUTOSAR DCM. Für jede unterstützte OBD-PID muss eine entsprechende Schnittstelleninstanz mit der Signatur <code>GetPIDValue</code> bereitgestellt werden, wobei <code>DataValueBuffer</code> vom Typ <code>uint8*</code> die serialisierten Nutzdaten empfängt und <code>Std_ReturnType</code> den Rückgabestatus (<code>E_OK</code>, <code>E_NOT_OK</code>) signalisiert.</p>"}], "trans": [{"from": "FIG-95373d0bac209d40", "to": "FIG-d815b31ba6c79aee", "fr": "R3.1.5", "tr": "R3.2.3", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\">\n<li><strong>UML-Rahmen</strong>: Der äußere Diagrammrahmen mit dem Kopf <code>class PidServices</code> entfällt.</li>\n<li><strong>Schnittstellenbezeichner</strong>: Der Interface-Name <code>PidServices_&lt;PID&gt;</code> ist nicht mehr fett/kursiv formatiert, sondern in Normalschrift gesetzt.</li>\n<li><strong>Typografie/Artefakte</strong>: Oberhalb des Rahmens sichtbare Textfragmente (<code>Dcm408).</code>) und der Schlagschatten des Interface-Blocks entfallen im bereinigten Bildausschnitt.</li>\n</ul>"}]};
